// Validates and normalizes the tool call. The LLM only provides `value` and
// `timezone`; `user_id` comes from the verified session in main_chat.
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const SLUG_RE = /^[a-z][a-z0-9_]*$/;
const EMAIL_RE = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;
const TZ_RE = /^(UTC|[A-Za-z]+(\/[A-Za-z0-9_+\-]+){1,2})$/;

const action = String($json.action ?? '');
const userId = String($json.user_id ?? '');
const value = String($json.value ?? '').trim();
const timezone = String($json.timezone ?? '').trim();

const ok = (extra = {}) => ({ json: { ok: true, action, user_id: userId, ...extra } });
const fail = (error) => ({ json: { ok: false, action, error } });

if (!UUID_RE.test(userId)) return fail('Not authenticated.');

switch (action) {
  case 'get_preferences':
  case 'get_my_data':
  case 'pause_newsletter':
  case 'resume_newsletter':
    return ok();

  case 'set_topics': {
    const topics = [...new Set(value.toLowerCase().split(/[\s,;]+/).filter(Boolean))];
    if (topics.length === 0) return fail('No topic given.');
    if (topics.length > 20 || topics.some((t) => t.length > 32 || !SLUG_RE.test(t))) {
      return fail('Invalid topics. Use comma-separated topic slugs.');
    }
    return ok({ topics: JSON.stringify(topics) });
  }

  case 'set_keywords': {
    const keywords = [...new Set(
      value.split(/[,;\n]+/)
        .map((k) => k.replace(/[\u0000-\u001f\u007f]/g, '').trim())
        .filter(Boolean)
    )];
    if (keywords.length > 10) return fail('Too many keywords (max 10).');
    if (keywords.some((k) => k.length > 40)) return fail('Each keyword must be at most 40 characters.');
    return ok({ keywords: JSON.stringify(keywords) });
  }

  case 'set_email': {
    const email = value.toLowerCase();
    if (email.length > 254 || !EMAIL_RE.test(email)) return fail('Invalid email address.');
    return ok({ email });
  }

  case 'set_schedule': {
    // Accepts "8", "08:00", "8h", "8h30", "8.30"
    const m = value.match(/^(\d{1,2})\s*(?:[:hH.]\s*(\d{2})?)?$/);
    if (!m) return fail('Invalid time. Use the 24h HH:MM format, e.g. 08:00.');
    const hours = Number(m[1]);
    const minutes = Number(m[2] ?? 0);
    if (hours > 23 || minutes > 59) return fail('Invalid time. Use the 24h HH:MM format, e.g. 08:00.');
    if (timezone && !TZ_RE.test(timezone)) return fail('Invalid timezone. Use an IANA name such as Europe/Paris.');
    const sendTime = String(hours).padStart(2, '0') + ':' + String(minutes).padStart(2, '0');
    return ok({ send_time: sendTime, timezone });
  }

  default:
    return fail('Unknown action.');
}

// Turns the query result into a short answer for the agent.
const action = $('Validate input').item.json.action;
const r = $json;
const list = (a) => (Array.isArray(a) && a.length ? a.join(', ') : 'none');

switch (action) {
  case 'get_preferences':
    return { json: {
      ok: true,
      username: r.username,
      email: r.email ?? 'not set',
      topics: list(r.topics),
      keywords: list(r.keywords),
      send_time: r.send_time ?? 'not set',
      timezone: r.timezone,
      newsletter_active: r.active,
      available_topics: list(r.available_topics),
    } };

  case 'set_topics': {
    if (!r.topics || r.topics.length === 0) {
      return { json: { ok: false, error: 'None of these topics exist. Nothing was changed.', available_topics: list(r.available_topics) } };
    }
    const json = { ok: true, message: 'Topics saved: ' + list(r.topics) + '.' };
    if (r.unknown && r.unknown.length) json.ignored_unknown_topics = list(r.unknown);
    return { json };
  }

  case 'set_keywords':
    return { json: { ok: true, message: 'Keywords saved: ' + list(r.keywords) + '.' } };

  case 'set_email':
    return { json: { ok: true, message: 'Email saved: ' + r.email + '.' } };

  case 'set_schedule':
    if (!r.send_time) {
      return { json: { ok: false, error: 'Unknown timezone. Use an IANA name such as Europe/Paris. Nothing was changed.' } };
    }
    return { json: { ok: true, message: 'Newsletter scheduled every day at ' + r.send_time + ' (' + r.timezone + ').' } };

  case 'get_my_data':
    return { json: {
      ok: true,
      note: 'This is all the personal data Persona stores about you. Your password is only stored as an irreversible hash.',
      username: r.username,
      email: r.email ?? 'not set',
      topics: list(r.topics),
      keywords: list(r.keywords),
      send_time: r.send_time ?? 'not set',
      timezone: r.timezone,
      newsletter_active: r.active,
      role: r.role,
      consent_given_at: r.consent_at,
      account_created_at: r.created_at,
      newsletters_received: r.newsletters_received,
      last_newsletter_at: r.last_newsletter_at ?? 'never',
      active_sessions: r.active_sessions,
    } };

  case 'pause_newsletter':
    return { json: { ok: true, message: 'Newsletter paused: no more emails will be sent until you resume it. Your settings are kept.' } };

  case 'resume_newsletter': {
    const missing = [];
    if (!r.email) missing.push('an email address');
    if (!r.send_time) missing.push('a delivery time');
    const json = { ok: true, message: 'Newsletter resumed.' };
    if (missing.length) json.warning = 'Nothing will be sent until you set ' + missing.join(' and ') + '.';
    return { json };
  }
}
return { json: { ok: false, error: 'Unknown action.' } };

parameters.query:
UPDATE users SET email = $2
WHERE id = $1::uuid
RETURNING email;

UPDATE users SET active = FALSE
WHERE id = $1::uuid
RETURNING active;

UPDATE users SET active = TRUE
WHERE id = $1::uuid
RETURNING active, email, to_char(send_time, 'HH24:MI') AS send_time, timezone;
